// Node: Build Site Related Lookups   ([SPL] Simpro -> HubSpot (Real Time))
// The Site was just CREATED in HubSpot. Work out which related Simpro records it should link to (LINKS)
// and ask HubSpot, in one batch read per related type, which of them already exist (by the unique
// Simpro ID property). Related records that are not in HubSpot are NOT created here - they are skipped.
// Returns no items when there is nothing to link, which ends the branch on purpose.
const record = $('Get Simpro Site').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const LINKS = [
  { key: 'company', toType: 'company', desired: (r) => (r.Customers ?? []).map(c => c.ID) },
  { key: 'primaryContact', toType: 'contact', desired: (r) => [r.PrimaryContact?.Contact?.ID] },
];

const OBJECTS = {
  company: { path: 'crm/objects/2026-09/companies', idProperty: 'simpro_customer_id' },
  contact: { path: 'crm/objects/2026-09/contacts', idProperty: 'simpro_contact_id' },
  site: { path: 'crm/objects/2026-09/0-420', idProperty: 'simpro_site_id' },
};

const needed = {}; // toType -> Set(related simpro ids)
for (const l of LINKS) {
  for (const id of (l.desired(record) ?? [])) {
    if (id === undefined || id === null || id === '') continue;
    (needed[l.toType] = needed[l.toType] ?? new Set()).add(String(id));
  }
}

const requests = [];
for (const [toType, set] of Object.entries(needed)) {
  const o = OBJECTS[toType];
  chunk([...set], 100).forEach((part, n) => requests.push({
    url: 'https://api.hubapi.com/' + o.path + '/batch/read',
    body: { idProperty: o.idProperty, properties: [o.idProperty], inputs: part.map(id => ({ id })) },
    meta: { toType, idProperty: o.idProperty, batch: n + 1 },
  }));
}
return requests.map(r => ({ json: r }));

// Node: Build Site Associations   ([SPL] Simpro -> HubSpot (Real Time))
// Links the newly created Site to the related records that already exist in HubSpot (one batch call per
// link type, default association). Related records not in HubSpot are skipped and listed in `skipped`
// so they are visible in the execution. Nothing is ever removed or updated here.
const record = $('Get Simpro Site').first().json;
const fromId = String($('Upsert Site in HubSpot').first().json.id);
const lookups = $('Build Site Related Lookups').all(); // the requests, in the order they were sent

const LINKS = [
  { key: 'company', toType: 'company', desired: (r) => (r.Customers ?? []).map(c => c.ID) },
  { key: 'primaryContact', toType: 'contact', desired: (r) => [r.PrimaryContact?.Contact?.ID] },
];

const OBJECTS = { company: 'companies', contact: 'contacts', site: '0-420' };

const found = {}; // toType -> { simproId: hubspotId }
$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = lookups[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return; // none of this batch exists in HubSpot
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('HubSpot lookup of related ' + meta.toType + ' failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  found[meta.toType] = found[meta.toType] ?? {};
  for (const x of ((r.body && r.body.results) || [])) {
    const sid = x.properties ? x.properties[meta.idProperty] : undefined;
    if (sid !== undefined && sid !== null) found[meta.toType][String(sid)] = String(x.id);
  }
});

const skipped = [];
const requests = [];
for (const l of LINKS) {
  const inputs = [];
  for (const relatedId of [...new Set((l.desired(record) ?? []).filter(v => v !== undefined && v !== null && v !== '').map(String))]) {
    const hs = found[l.toType] ? found[l.toType][relatedId] : undefined;
    if (hs) inputs.push({ from: { id: fromId }, to: { id: hs } });
    else skipped.push({ link: l.key, relatedSimproId: relatedId, reason: 'not in HubSpot - link skipped' });
  }
  if (inputs.length) {
    requests.push({
      url: 'https://api.hubapi.com/crm/v4/associations/0-420/' + OBJECTS[l.toType] + '/batch/associate/default',
      body: { inputs },
      meta: { link: l.key, count: inputs.length },
    });
  }
}
// Make skipped links visible even when nothing is left to link (no items = nothing else to look at).
if (skipped.length) $execution.customData.set('skippedLinks', skipped.map(s => s.link + ':' + s.relatedSimproId).join(', ').slice(0, 250));
return requests.map(r => ({ json: { ...r, skipped } }));

